# dconf (and vala, which dconf builds with) need glib2, and glib2 lists dconf only for its test suite and as a runtime option.
drop dconf
# Arch builds glib2 twice: gobject-introspection needs glib2 and glib2 needs gobject-introspection for its .gir files.
# Here glib2 is built without introspection and documentation (gi-docgen).
drop gobject-introspection
drop gi-docgen
sub -D documentation=true => -D documentation=false
sub -D introspection=enabled => -D introspection=disabled
sub mv "$f" "$d"; => mv "$f" "$d" || true;
add libsysprof-capture
